from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    # The line maze partitions the background. Small bounded pockets can be
    # closed against the canvas edge as well as against the line color.
    max_pocket = (h * w) // 10
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            region = []
            while q:
                x, y = q.popleft()
                region.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == bg and (a, b) not in seen:
                        seen.add((a, b))
                        q.append((a, b))
            if len(region) <= max_pocket:
                for x, y in region:
                    out[x][y] = 4
    return out

