from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    inks = {v for row in grid for v in row if v != bg}
    out = [row[:] for row in grid]
    for ink in inks:
        # Rectangles have three or four continuous colored sides. A canvas
        # boundary may supply the missing side for a frame open at that edge.
        for top in range(h):
            for bottom in range(top + 2, h):
                for left in range(w):
                    for right in range(left + 2, w):
                        sides = [
                            top == 0 or all(grid[top][c] == ink for c in range(left, right + 1)),
                            bottom == h - 1 or all(grid[bottom][c] == ink for c in range(left, right + 1)),
                            left == 0 or all(grid[r][left] == ink for r in range(top, bottom + 1)),
                            right == w - 1 or all(grid[r][right] == ink for r in range(top, bottom + 1)),
                        ]
                        if sum(sides) < 3:
                            continue
                        for r in range(top + 1, bottom):
                            for c in range(left + 1, right):
                                if grid[r][c] == bg:
                                    out[r][c] = 4
    return out

