    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            q = deque([(r, c)]); seen.add((r, c)); comp = []
            while q:
                x, y = q.popleft(); comp.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == bg and (nx, ny) not in seen:
                        seen.add((nx, ny)); q.append((nx, ny))
            if not any(x in (0, h - 1) or y in (0, w - 1) for x, y in comp):
                for x, y in comp:
                    out[x][y] = 4
    # A three-sided frame that has continuous rails to the bottom edge and a
    # complete top stroke encloses a region closed by the canvas boundary.
    for ink in {v for row in grid for v in row if v != bg}:
        for top in range(h - 1):
            for left in range(w - 2):
                for right in range(left + 2, w):
