from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            q = deque([(r, c)]); seen.add((r, c)); comp = []
            while q:
                x, y = q.popleft(); comp.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == bg and (nx, ny) not in seen:
                        seen.add((nx, ny)); q.append((nx, ny))
            if not any(x in (0, h - 1) or y in (0, w - 1) for x, y in comp):
                for x, y in comp:
                    out[x][y] = 4
    # The fourth side of a frame can coincide with the canvas boundary.
    for ink in {v for row in grid for v in row if v != bg}:
        # Top-boundary-open frame: vertical rails descend from row 0 to a bottom bar.
        for bottom in range(1, h):
            for left in range(w - 2):
                for right in range(left + 2, w):
                    if not all(grid[bottom][c] == ink for c in range(left, right + 1)):
                        continue
                    if left > 0 and grid[bottom][left - 1] == ink:
                        continue
                    if right + 1 < w and grid[bottom][right + 1] == ink:
                        continue
                    if all(grid[r][left] == ink and grid[r][right] == ink for r in range(bottom + 1)):
                        for r in range(bottom):
                            for c in range(left + 1, right):
                                if grid[r][c] == bg:
                                    out[r][c] = 4
        # Bottom-boundary-open frame: top bar and rails reach the last row.
        for top in range(h - 1):
            for left in range(w - 2):
                for right in range(left + 2, w):
                    if not all(grid[top][c] == ink for c in range(left, right + 1)):
                        continue
                    if left > 0 and grid[top][left - 1] == ink:
                        continue
                    if right + 1 < w and grid[top][right + 1] == ink:
                        continue
                    if all(grid[r][left] == ink and grid[r][right] == ink for r in range(top, h)):
                        for r in range(top + 1, h):
                            for c in range(left + 1, right):
                                if grid[r][c] == bg:
                                    out[r][c] = 4
    return out

