def transform(grid):
    h, w = len(grid), len(grid[0])
    # Solid 3-lines are panel separators.
    sep_rows = [r for r, row in enumerate(grid) if all(v == 3 for v in row)]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    def bounds(size, cuts):
        starts = [0] + [x + 1 for x in cuts]
        ends = cuts + [size]
        return list(zip(starts, ends))
    row_panels = bounds(h, sep_rows)
    col_panels = bounds(w, sep_cols)
    vals = [v for row in grid for v in row if v != 3]
    bg = max(set(vals), key=vals.count)
    # Source panel is the one containing the most non-background pattern cells.
    best = None
    for ri, (r0, r1) in enumerate(row_panels):
        for ci, (c0, c1) in enumerate(col_panels):
            cells = [(r-r0, c-c0, grid[r][c])
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != bg and grid[r][c] != 3]
            if best is None or len(cells) > len(best[2]):
                best = (ri, ci, cells, r1-r0, c1-c0)
    if best is None or not best[2]:
        return [row[:] for row in grid]
    sri, sci, marks, sh, sw = best
    out = [row[:] for row in grid]
    for ri, (r0, r1) in enumerate(row_panels):
        for ci, (c0, c1) in enumerate(col_panels):
            if (r1-r0, c1-c0) != (sh, sw):
                continue
            for dr, dc, color in marks:
                out[r0+dr][c0+dc] = color
    return out

