        for row in got: print(row)
    test = [[2,2,2,2,2,2,2] for _ in range(6)] + [[3]*7] + [[2,2,2,2,2,2,2] for _ in range(6)] + [[3]*7] + [[2,2,2,2,2,5,7],[2,2,2,2,7,2,2],[2,2,2,2,2,5,2],[2,2,2,2,2,2,2],[2,6,5,2,2,2,2],[2,6,2,2,2,2,2]]
