from collections import deque

def components(grid, background):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q, cells = deque([(r, c)]), []
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            result.append((color, cells))
    return result

def transform(grid):
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = components(grid, background)
    # Recolor the smallest non-background object, preserving the marker's color.
    def marker_score(item):
        cells = item[1]
        rows, cols = Counter(r for r,c in cells), Counter(c for r,c in cells)
        return max(rows.values()) + max(cols.values())
    marker = max(comps, key=marker_score)
    candidates = [obj for color,obj in comps if color == 0 and obj is not marker]
    if not candidates:
        candidates = [obj for color,obj in comps if obj is not marker]
    target = min(candidates, key=len)
    out = [row[:] for row in grid]
    for r,c in target:
        out[r][c] = marker[0]
    return out

