            up = sum((y, c) in cells for y in range(r-1, -1, -1))
            down = sum((y, c) in cells for y in range(r+1, h))
            left = sum((r, x) in cells for x in range(c-1, -1, -1))
            right = sum((r, x) in cells for x in range(c+1, w))
