def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 2 or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = y+dy, x+dx
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p); cells.add(p); q.append(p)
            comps.append((color, cells))

    # A color-key line is a long L-shaped edge component; recolor the closest
    # separate object along the line's inward-facing horizontal projection.
    markers = []
    for color, cells in comps:
        rs = [r for r,c in cells]; cs = [c for r,c in cells]
        r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
        if len(cells) >= 8 and r1-r0 >= 3 and c1-c0 >= 4:
            if c1 == w-1 and r0 == 0:
                markers.append((color,cells,r0,r1,c0,c1))
    if markers:
        color, marker, r0,r1,c0,c1 = max(markers,key=lambda x:len(x[1]))
        # target is the closest non-background component in the marker's
        # vertical span, on its inward side (left of a right-edge marker).
        candidates=[]
        for co,obj in comps:
            if obj == marker: continue
            for r,c in obj:
                if r0 <= r <= r1 and c < c0:
                    candidates.append((c0-c, abs(r-r0), obj))
        if candidates:
            target=min(candidates,key=lambda x:(x[0],x[1]))[2]
            for r,c in target: out[r][c]=color
    return out

