from collections import Counter, deque


def components(grid, color):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            obj = set()
            while q:
                y, x = q.popleft()
                obj.add((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            result.append(obj)
    return result


def l_info(obj):
    rs, cs = [r for r,c in obj], [c for r,c in obj]
    for r in (min(rs), max(rs)):
        for c in (min(cs), max(cs)):
            vr = sorted(y for y,x in obj if x == c)
            hc = sorted(x for y,x in obj if y == r)
            if len(vr) < 2 or len(hc) < 2:
                continue
            expected = ({(y,c) for y in range(min(vr),max(vr)+1)} |
                        {(r,x) for x in range(min(hc),max(hc)+1)})
            if expected == obj:
                vdir = 1 if max(vr) > r else -1
                hdir = 1 if max(hc) > c else -1
                return r,c,-vdir,-hdir
    return None


def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps={color:components(grid,color) for color in set(sum(grid,[])) if color!=bg}
    guides=[]
    for color, objs in comps.items():
        for obj in objs:
            info=l_info(obj)
            if info: guides.append((len(obj),color,obj,info))
    out=[row[:] for row in grid]
    if not guides: return out
    # The largest L is the directional color key.
    _, color, guide, (r,c,dr,dc)=max(guides,key=lambda x:x[0])
    candidates=[]
    for other, objs in comps.items():
        for obj in objs:
            if obj is guide: continue
            rows=[y for y,x in obj]; cols=[x for y,x in obj]
            # Choose a target in the open quadrant of the L.
            if (min(rows) < r if dr < 0 else max(rows) > r) and (min(cols) < c if dc < 0 else max(cols) > c):
                dy=max(0,min(rows)-r,r-max(rows)); dx=max(0,min(cols)-c,c-max(cols))
                candidates.append((dy*dy+dx*dx, obj))
    if candidates:
        target=min(candidates,key=lambda x:x[0])[1]
        for y,x in target: out[y][x]=color
    return out

if __name__ == '__main__':
    import json,sys
    print(json.dumps(transform(json.load(sys.stdin))))

