    bars = {0: [], w - 1: []}
    for col in bars:
        start = None
        for r in range(h + 1):
            active = r < h and grid[r][col] != bg
            if active and start is None:
                start = r
            elif not active and start is not None:
                bars[col].append((start, r - 1, grid[start][col]))
                start = None

    edge_colors = {color for runs in bars.values() for _, _, color in runs}
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(1, w - 1)
