def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    freq = {}
    for row in grid:
        for v in row:
            freq[v] = freq.get(v, 0) + 1
    bg = max(freq, key=freq.get)

    # Detect bars as contiguous same-color boundary runs of length >= 2.
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            color = grid[r][c]
            a = c
            while c < w and grid[r][c] == color:
                c += 1
            if c - a >= 2:
                bars.append(('h', r, a, c, color))
    for c in (0, w - 1):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            color = grid[r][c]
            a = r
            while r < h and grid[r][c] == color:
                r += 1
            if r - a >= 2:
                bars.append(('v', c, a, r, color))

    # All off-bar colored pixels are markers. The marker color is projected
    # perpendicularly from every bar cell; rays stop on the first marker and
    # recolor that hit with 4. Unhit markers remain unchanged.
    bar_cells = set()
    for kind, edge, a, b, color in bars:
        if kind == 'h':
            bar_cells.update((edge, c) for c in range(a, b))
        else:
            bar_cells.update((r, edge) for r in range(a, b))
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r, c) not in bar_cells]
    if not markers:
        return out
    ray_color = markers[0][2]

    for kind, edge, a, b, color in bars:
        for pos in range(a, b):
            if kind == 'h':
                r = edge + (1 if edge == 0 else -1)
                c = pos
                dr, dc = (1 if edge == 0 else -1), 0
            else:
                r = pos
                c = edge + (1 if edge == 0 else -1)
                dr, dc = 0, (1 if edge == 0 else -1)
            while 0 <= r < h and 0 <= c < w:
                if grid[r][c] != bg:
                    if (r, c) not in bar_cells:
                        out[r][c] = 4
                    break
                out[r][c] = ray_color
                r += dr
                c += dc
    return out

