            r, c = coords[i]
            color = grid[r][c]
            if color == bg:
                i += 1
                continue
            j = i + 1
            while j < len(coords) and grid[coords[j][0]][coords[j][1]] == color:
                j += 1
            if j - i >= 2:
                result.append((color, i, j))
            i = j
        return result

