    for side, rs in (("top", top), ("bottom", bottom), ("left", left), ("right", right)):
        for color, a, b in rs:
            for i in range(a, b):
                edge_bar_cells.add((0 if side == "top" else h - 1, i) if side in ("top", "bottom")
                                   else (i, 0 if side == "left" else w - 1))
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and (r, c) not in edge_bar_cells:
                markers.append((r, c, grid[r][c]))

    for r, c, color in markers:
        for a_side, b_side, bar_color, start, end, other_start in pairs:
            axis = c if a_side == "top" else r
            if not (start <= axis < end):
                continue
            slot = axis - start
            for side, run_start in ((a_side, start), (b_side, other_start)):
                pos = run_start + slot
                if side == "top":
                    step, rr, cc = 1, 0, pos
                elif side == "bottom":
                    step, rr, cc = -1, h - 1, pos
                elif side == "left":
                    step, rr, cc = 1, pos, 0
                else:
                    step, rr, cc = -1, pos, w - 1
                marker_side = ((a_side == "top" and r in (0, h-1)) or
