def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Background is the most frequent color. Find paired equal-length bars
    # on top and bottom edges; the offset within a bar maps to the other edge.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    def get_runs(row):
        runs = []
        i = 0
        while i < len(row):
            if row[i] == bg:
                i += 1
                continue
            j = i + 1
            while j < len(row) and row[j] == row[i]:
                j += 1
            if j-i >= 2:
                runs.append((row[i], i, j))
            i = j
        return runs

    top, bottom = get_runs(grid[0]), get_runs(grid[-1])
    for color, start, end in top:
        mate_start = next((s for col, s, e in bottom
                           if col == color and e-s == end-start), None)
        if mate_start is None:
            continue
        length = end-start
        for slot in range(length):
            tc, bc = start+slot, mate_start+slot
            # A non-background interior pixel in this bar-aligned column
            # selects this slot and supplies the projected ray color.
            markers = [(r, grid[r][tc]) for r in range(1, h-1)
                       if grid[r][tc] != bg]
            if not markers:
                continue
            for r, marker_color in markers:
                # Project from the top bar down through the marker, stopping
                # at and recoloring the marker.
                for rr in range(1, r):
                    if grid[rr][tc] == bg:
                        out[rr][tc] = marker_color
                out[r][tc] = 4
                # The matching slot on the opposite bar projects the full
                # interior ray toward the other edge.
                for rr in range(1, h-1):
                    if grid[rr][bc] == bg:
                        out[rr][bc] = marker_color
    return out

