    freq = {}
    for row in grid:
        for v in row:
            freq[v] = freq.get(v, 0) + 1
    bg = max(freq, key=freq.get)

    def get_runs(values):
        result = []
        i = 0
        while i < len(values):
            if values[i] == bg:
                i += 1
                continue
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if j - i >= 2:
                result.append((values[i], i, j))
            i = j
        return result

    edge_runs = {
        'top': get_runs(grid[0]),
        'bottom': get_runs(grid[-1]),
        'left': get_runs([grid[r][0] for r in range(h)]),
        'right': get_runs([grid[r][-1] for r in range(h)]),
    }
    opposite = {'top': 'bottom', 'bottom': 'top', 'left': 'right', 'right': 'left'}
    pairs = []
    for side in ('top', 'left'):
        other = opposite[side]
        used = set()
        for color, start, end in edge_runs[side]:
            for idx, (oc, os, oe) in enumerate(edge_runs[other]):
                if idx not in used and color == oc and end-start == oe-os:
                    pairs.append((side, other, start, os, end-start))
                    used.add(idx)
                    break

    def ray(side, pos, k):
        if side == 'top': return (k, pos)
        if side == 'bottom': return (h-1-k, pos)
        if side == 'left': return (pos, k)
        return (pos, w-1-k)

    def extent(side): return h if side in ('top','bottom') else w

    for side_a, side_b, start_a, start_b, length in pairs:
        for slot in range(length):
            pos_a, pos_b = start_a+slot, start_b+slot
            candidates = []
            for side, pos in ((side_a,pos_a),(side_b,pos_b)):
                for k in range(1, extent(side)-1):
                    r,c = ray(side,pos,k)
                    if grid[r][c] != bg:
                        candidates.append((side,pos,k,grid[r][c]))
                        break
            for marker_side, marker_pos, depth, color in candidates:
                r,c = ray(marker_side, marker_pos, depth)
                out[r][c] = 4
                # Cast the marker color from the corresponding opposite bar
                # toward the other edge until a pre-existing object is met.
                far_side = side_b if marker_side == side_a else side_a
                far_pos = pos_b if marker_side == side_a else pos_a
                for k in range(1, extent(far_side)-1):
                    rr,cc = ray(far_side,far_pos,k)
                    if grid[rr][cc] != bg:
                        break
                    out[rr][cc] = color
                # The unoccupied segment between source edge and marker is
                # also filled in the source ray direction.
                for k in range(1, depth):
