        'bottom': runs(grid[-1]),
        'left': runs([grid[r][0] for r in range(h)]),
        'right': runs([grid[r][-1] for r in range(h)]),
    }
    pairs = []
    for a, b in (('top','bottom'), ('left','right')):
        used = set()
        for color, start, end in edges[a]:
            for idx, (other, start2, end2) in enumerate(edges[b]):
                if idx not in used and color == other and end-start == end2-start2:
                    pairs.append((a, b, start, start2, end-start))
                    used.add(idx)
