    def get_runs(values):
        runs = []
        i = 0
        while i < len(values):
            if values[i] == bg:
                i += 1
                continue
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if j - i >= 2:
                runs.append((values[i], i, j))
            i = j
        return runs

    edge_runs = {
        'top': get_runs(grid[0]),
        'bottom': get_runs(grid[-1]),
        'left': get_runs([grid[r][0] for r in range(h)]),
        'right': get_runs([grid[r][-1] for r in range(h)]),
    }
    pairs = []
    for first, second in (('top', 'bottom'), ('left', 'right')):
        used = set()
        for color, start, end in edge_runs[first]:
            for idx, (other, other_start, other_end) in enumerate(edge_runs[second]):
                if idx not in used and color == other and end-start == other_end-other_start:
                    pairs.append((first, second, start, other_start, end-start))
                    used.add(idx)
                    break

    def pos_for(side, index, depth):
        if side == 'top': return depth, index
        if side == 'bottom': return h-1-depth, index
        if side == 'left': return index, depth
        return index, w-1-depth

    def depth_limit(side):
        return h if side in ('top','bottom') else w

    for side_a, side_b, start_a, start_b, length in pairs:
        for r in range(h):
            for c in range(w):
                marker = grid[r][c]
                if marker == bg:
                    continue
                axis = c if side_a == 'top' else r
                source = None
                slot = None
                if start_a <= axis < start_a+length:
                    source, slot = side_a, axis-start_a
                elif start_b <= axis < start_b+length:
                    source, slot = side_b, axis-start_b
                if source is None:
                    continue
                other = side_b if source == side_a else side_a
                source_index = (start_a if source == side_a else start_b) + slot
                other_index = (start_b if source == side_a else start_a) + slot
                # Source-side ray runs from its bar to marker unless marker is
                # on a perpendicular outer edge; opposite paired ray runs full.
                on_perpendicular_edge = (c == 0 or c == w-1) if side_a in ('top','bottom') else (r == 0 or r == h-1)
                if not on_perpendicular_edge:
                    for depth in range(1, depth_limit(source)):
                        rr, cc = pos_for(source, source_index, depth)
                        if (rr,cc) == (r,c):
