                            break
                        if grid[rr][cc] != bg:
                            break
                        out[rr][cc] = marker
                else:
                    out[r][c] = 4
                for depth in range(1, depth_limit(other)-1):
                    rr, cc = pos_for(other, other_index, depth)
                    if grid[rr][cc] != bg:
                        break
                    out[rr][cc] = marker
    return out

