    # a set of straight, slot-aligned rays. A non-background pixel on a ray is
    # changed to 4, while clear cells on that same ray receive its color.
    def find_runs(values):
        result = []
        i = 0
        while i < len(values):
            if values[i] == background:
                i += 1
                continue
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if j - i >= 2:
                result.append((values[i], i, j))
            i = j
        return result

    edges = {
        'top': find_runs(grid[0]),
        'bottom': find_runs(grid[-1]),
        'left': find_runs([grid[r][0] for r in range(h)]),
        'right': find_runs([grid[r][-1] for r in range(h)]),
    }
    pairs = []
    for first, second in (('top', 'bottom'), ('left', 'right')):
        used = set()
        for color, start, end in edges[first]:
            for index, (other, s, e) in enumerate(edges[second]):
                if index not in used and color == other and end - start == e - s:
                    pairs.append((first, second, start, s, end - start))
                    used.add(index)
                    break

    def point(side, offset, depth):
        if side == 'top': return depth, offset
        if side == 'bottom': return h - 1 - depth, offset
        if side == 'left': return offset, depth
        return offset, w - 1 - depth

    for first, second, start_a, start_b, length in pairs:
        for slot in range(length):
            pos_a, pos_b = start_a + slot, start_b + slot
            extent = h - 1 if first in ('top', 'bottom') else w - 1
            # Inspect each paired ray, stopping at its first obstacle. Color
            # clear cells with the marker hue, and turn that marker into 4.
            for side, pos in ((first, pos_a), (second, pos_b)):
                for depth in range(1, extent):
                    r, c = point(side, pos, depth)
                    if grid[r][c] != background:
