    # corresponding straight lines through the grid.
    edge_data = [
        ('top', 'bottom', runs(grid[0]), runs(grid[-1])),
        ('left', 'right', runs([grid[r][0] for r in range(h)]),
         runs([grid[r][-1] for r in range(h)])),
    ]

    def cell(side, pos, depth):
        if side == 'top': return depth, pos
        if side == 'bottom': return h - 1 - depth, pos
        if side == 'left': return pos, depth
        return pos, w - 1 - depth

    def depth_size(side):
