            for idx, (color_b, start_b, end_b) in enumerate(bars_b):
                if idx not in used and color == color_b and end_a-start_a == end_b-start_b:
                    match = (idx, start_b)
                    break
            if match is None:
                continue
            used.add(match[0])
            start_b = match[1]
