                for side, pos, opposite, opposite_pos in (
                    (side_a, pos_a, side_b, pos_b),
                    (side_b, pos_b, side_a, pos_a),
                ):
                    # A marker on this slot paints from its own edge up to
                    # itself, then its color projects through the matching
                    # slot from the opposite edge. Marker pixels become 4.
                    for depth in range(1, depth_size(side) - 1):
                        r, c = cell(side, pos, depth)
