        out_runs, i = [], 0
        while i < len(values):
            if values[i] == bg:
                i += 1
                continue
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if j - i >= 2:
                out_runs.append((values[i], i, j))
            i = j
        return out_runs

