                else:
                    r, marker_color = markers[-1]
                    for rr in range(r + 1, h - 1):
                        if grid[rr][col] == bg:
                            out[rr][col] = marker_color
                    out[r][col] = 4
                    for rr in range(h - 2, 0, -1):
                        if grid[rr][opp_col] != bg:
                            break
                        out[rr][opp_col] = marker_color
    return out

