def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    freq = {}
    for row in grid:
        for value in row:
            freq[value] = freq.get(value, 0) + 1
    background = max(freq, key=freq.get)

    def runs(values):
        result = []
        i = 0
        while i < len(values):
            if values[i] == background:
                i += 1
                continue
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if j - i >= 2:
                result.append((values[i], i, j))
            i = j
        return result

    # Opposing matching bars pair their slots. A marker on a bar's aligned
    # ray colors the segment from that bar through the marker and the clear
    # matching ray from the opposite bar. The marker becomes 4.
    edge_specs = (
        ('top', 'bottom', runs(grid[0]), runs(grid[-1])),
        ('left', 'right', runs([grid[r][0] for r in range(h)]),
         runs([grid[r][-1] for r in range(h)])),
    )
    for side_a, side_b, bars_a, bars_b in edge_specs:
        used = set()
        for color, start_a, end_a in bars_a:
            match = None
            for index, (other, start_b, end_b) in enumerate(bars_b):
                if index not in used and color == other and end_a - start_a == end_b - start_b:
                    match = (index, start_b)
                    break
