def _period(clues):
    keys = list(clues)
    if len(keys) == 1:
        return 1
    span = max(keys) - min(keys) + 1
    # The shortest period that makes every observed stripe consistent is
    # the minimal repeating template supported by the clues.
    for period in range(1, span + 1):
        residues = {}
        valid = True
        for key, color in clues.items():
            residue = key % period
            if residue in residues and residues[residue] != color:
                valid = False
                break
            residues[residue] = color
        if valid:
            return period
    return span


