def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    mask = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 3]
    if not mask:
        return g
    r0, r1 = min(r for r, _ in mask), max(r for r, _ in mask)
    c0, c1 = min(c for _, c in mask), max(c for _, c in mask)
    mh, mw = r1-r0+1, c1-c0+1
    horizontal = mw >= mh
    size = mh if horizontal else mw
    stride = size + 1
    nr, nc = (h+1)//stride, (w+1)//stride
    masked_row = r0//stride if horizontal else None
    masked_col = c0//stride if not horizontal else None

    # A visible tile is the repeated motif; its own occupied cells encode the
    # larger tile-lattice pattern.
    candidates = []
    for tr in range(nr):
        for tc in range(nc):
            if (horizontal and tr == masked_row) or (not horizontal and tc == masked_col):
                continue
            rr, cc = tr*stride, tc*stride
            tile = [[g[rr+dr][cc+dc] for dc in range(size)] for dr in range(size)]
            count = sum(v == 2 for row in tile for v in row)
            if count:
                candidates.append((count, tile))
    if not candidates:
        return g
    _, motif = max(candidates, key=lambda item: item[0])

    # The mask hides exactly the tiles selected by the motif at its lattice
    # coordinates. Clear it, then restore those tiles from the motif.
    for r, c in mask:
        g[r][c] = 0
    for tr in range(nr):
        for tc in range(nc):
            if tr >= size or tc >= size or motif[tr][tc] != 2:
                continue
            rr, cc = tr*stride, tc*stride
            if (horizontal and tr == masked_row) or (not horizontal and tc == masked_col):
                for dr in range(size):
                    for dc in range(size):
                        g[rr+dr][cc+dc] = motif[dr][dc]

    # Mark each present tile at the local coordinate of its lattice position.
    for tr in range(nr):
        for tc in range(nc):
            if tr >= size or tc >= size or motif[tr][tc] != 2:
                continue
            rr, cc = tr*stride+tr, tc*stride+tc
            if rr < h and cc < w and g[rr][cc] == 2:
                g[rr][cc] = 8
    return g

