from collections import deque

def comps(g):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   col=g[r][c]
   if col==2 or (r,c) in seen: continue
   q=deque([(r,c)]); seen.add((r,c)); cells={(r,c)}
   while q:
    y,x=q.popleft()
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     p=y+dy,x+dx
     if 0<=p[0]<h and 0<=p[1]<w and p not in seen and g[p[0]][p[1]]==col:
      seen.add(p);cells.add(p);q.append(p)
   out.append((col,cells))
 return out

def transform(g):
 out=[row[:] for row in g]; parts=comps(g); h,w=len(g),len(g[0])
 # The longest edge-attached straight bar indicates the color to use; color
 # the nearest object lying directly behind the bar, across the background.
 bars=[]
 for color,cells in parts:
  rs=[r for r,c in cells];cs=[c for r,c in cells]
  r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
  if (r0==r1 and len(cells)>=4 and (r0 in (0,h-1) or c0==0 or c1==w-1)) or (c0==c1 and len(cells)>=4 and (c0 in (0,w-1))):
   bars.append((len(cells),color,cells,r0,r1,c0,c1))
 if not bars:return out
 _,color,bar,r0,r1,c0,c1=max(bars)
 # Along inward-facing perpendicular rays, find nearest non-key component.
 rays=[]
 if r0==r1:
  dr=1 if r0==0 else -1
  rays=[(r0+dr*k,c) for c in range(c0,c1+1) for k in range(1,h)]
 elif c0==0 or c1==w-1:
  dc=1 if c0==0 else -1
  rays=[(r,c0+dc*k) for r in range(r0,r1+1) for k in range(1,w)]
 for y,x in rays:
  if 0<=y<h and 0<=x<w and g[y][x]!=2 and g[y][x]!=color:
   target_color=g[y][x]
   for co,obj in parts:
    if co==target_color and (y,x) in obj:
     for a,b in obj:out[a][b]=color
     return out
 return out
