from collections import deque

def transform(grid):
    out=[row[:] for row in grid];h,w=len(grid),len(grid[0]);seen=set();parts=[]
    for r in range(h):
      for c in range(w):
       color=grid[r][c]
       if color==2 or (r,c) in seen: continue
       cells={(r,c)};seen.add((r,c));q=deque([(r,c)])
       while q:
        y,x=q.popleft()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         p=y+dy,x+dx
         if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==color:
          seen.add(p);cells.add(p);q.append(p)
       parts.append((color,cells))
    for color,marker in parts:
      rs=[r for r,c in marker];cs=[c for r,c in marker];r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
      if len(marker)<8 or (r1-r0)<3 or (c1-c0)<5:continue
      if not (r0==0 or r1==h-1 or c0==0 or c1==w-1):continue
      # Only transform compact pattern groups with colors other than marker
      targets=[]
      for oc,obj in parts:
       if obj==marker or len(obj)<2:continue
       ors=[r for r,c in obj];ocs=[c for r,c in obj]
       # object is within marker bounding-box reach and in a corner's inward quadrant
       if max(ors)<=r1 and min(ocs)>=c0 and min(ocs)<c1:
        dist=min(abs(r-y)+abs(c-x) for r,c in obj for y,x in marker)
        targets.append((dist,-len(obj),obj))
      if targets:
       target=min(targets)[2]
       for r,c in target:out[r][c]=color
       return out
    return out

